def w3(n):
    s = []
    h = n // 100
    r = n % 100
    if h:
        s.append("yüz" if h == 1 else ONES[h] + " yüz")
    if r // 10:
        s.append(TENS[r // 10])
    if r % 10:
        s.append(ONES[r % 10])
    return " ".join(s)


def words(n):
    n = int(n)
    if n == 0:
        return "sıfır"
    parts = []
    for val, nm in ((1000000000, "milyar"), (1000000, "milyon"), (1000, "bin")):
        q = n // val
        if q:
            parts.append("bin" if (val == 1000 and q == 1) else w3(q) + " " + nm)
            n = n % val
    if n:
        parts.append(w3(n))
    return " ".join(parts)


def num(x):
    try:
        return float(x)
    except Exception:
        return None


def amt(x, cur):
    v = abs(num(x) or 0.0)
    cents = int(round(v * 100))
    whole = cents // 100
    frac = cents % 100
    name = [c for c in CUR if c[0] == cur][0]
    t = words(whole) + " " + name[1]
    if frac:
        t += " " + words(frac) + " " + name[2]
    return t


SUF = {"Lirası": "'dır", "Dolar": "'dır", "Euro": "'dur", "Sterlini": "'dir", "kuruş": "tur", "sent": "tir", "peni": "dir"}


def dir_(t):
    last = t.split(" ")[-1]
    return t + SUF.get(last, "'dir")


def pdate(s):
    s = str(s or "").strip()
    try:
        dd, mm, yy = s.split(".")
        return _dt.date(int(yy), int(mm), int(dd))
    except Exception:
        return None


def sdate(d):
    return "%d %s %d" % (d.day, MON[d.month - 1], d.year)


YSUF = {"0": "'dır", "1": "'dir", "2": "'dir", "3": "'tür", "4": "'tür", "5": "'tir", "6": "'dır", "7": "'dir", "8": "'dir", "9": "'dur"}


def dir_date(d):
    y = str(d.year)
    suf = YSUF.get(y[-1], "'dir")
    if y[-1] == "0":
        suf = dict(zip("123456789", ["'dur", "'dir", "'dur", "'tır", "'dir", "'tır", "'tir", "'dir", "'dır"])).get(y[-2], "'dır")
    return sdate(d) + suf


